-- schema_catch_up
--
-- Brings a database built from the baseline plus every earlier migration to exactly the shape of
-- prisma/schema.prisma. Roughly three quarters of the schema (115 tables, 275 indexes, 30 column
-- additions, 21 table rebuilds) was only ever created in real databases with `prisma db push`, so no
-- migration described it. This script is generated by Prisma, not hand-written:
--
--   prisma migrate diff --from-url file:<baseline + all earlier migrations> \
--                       --to-schema-datamodel prisma/schema.prisma --script
--
-- WHO RUNS THIS
--   * Clean databases (local, CI, staging bootstrap): `prisma migrate deploy` runs it normally.
--     Tables are empty, so the rebuilds below are safe.
--   * Databases already created by `prisma db push` (production today) ALREADY have this schema.
--     Do NOT execute this SQL there. Record it as applied instead, along with the earlier migrations:
--       prisma migrate resolve --applied 20261107100000_schema_catch_up
--     (see prisma/migrations/README.md).
--
-- DATA WARNING
--   The table rebuilds below copy only columns that exist in BOTH the old and new shape. Three
--   tables lose columns that schema.prisma no longer declares; any data in them is not carried over:
--     AppActivityLog       message, metadataJson, requestId
--     Retainer             taxRate
--     TaxDecisionAuditLog  action, actorEmail, actorUserId, canonicalPayload, decisionSource,
--                          effectiveFrom, effectiveTo, entryHash, newValues, prevHash,
--                          previousValues, rate, reason, scopeRef, scopeType, taxRateOverrideId
--   Never run this SQL against a database that holds rows in those tables.

-- AlterTable
ALTER TABLE "Expense" ADD COLUMN "withholdingAmount" DECIMAL;
ALTER TABLE "Expense" ADD COLUMN "withholdingDeductedAt" DATETIME;
ALTER TABLE "Expense" ADD COLUMN "withholdingDepositDueAt" DATETIME;
ALTER TABLE "Expense" ADD COLUMN "withholdingDepositedAt" DATETIME;
ALTER TABLE "Expense" ADD COLUMN "withholdingRatePercent" DECIMAL;
ALTER TABLE "Expense" ADD COLUMN "withholdingReminderSentAt" DATETIME;

-- AlterTable
ALTER TABLE "ServiceTemplate" ADD COLUMN "imageUrl" TEXT;
ALTER TABLE "ServiceTemplate" ADD COLUMN "longDescription" TEXT;

-- AlterTable
ALTER TABLE "UserOnboarding" ADD COLUMN "persona" TEXT;

